\begin{enumerate}
\item For any $x\in\mathbb{R}^n$ there exists a fixed $\beta\in [1,2)$ such that
\begin{align}
\|x-\beta \cdot Q_{\mathrm{FP4}}(\beta^{-1} x)\|^2\leq \sum_{i=1}^n x_i^2 \phi(x_i).   
\end{align}
\item $\phi(x)$ is an even function. Its minimum is $\phi_{\mathrm{min}}=\mathbb{E}[(1-2^{-(U+1)}\mathrm{round}(2^{U+1}))^2]\approx 0.010723$ and it attains this minimum on the entire interval $\mathcal{I}_{\mathrm{FP4}}=[7/4,7]$. 
\end{enumerate}
\label{lem:randFP4props}

Substituting~\eqref{eq:QtDef} into the definition of $\phi$ and using $U\sim\mathrm{Uniform}([0,1))$ gives
\begin{align}
 \phi(2^t)
 &=\mathbb{E}_U\left[\left(1-2^{U-t}Q_{\mathrm{FP4}}(2^{t-U})\right)^2\right]\nonumber\\
 &=\int_0^1\left(1-2^{u-t}Q_{\mathrm{FP4}}(2^{t-u})\right)^2\,du.
 \label{eq:phi-dither-expectation}
\end{align}
The substitution $v=t-u$, with $du=-dv$, yields~\eqref{eq:phi-log-integral-proof}.

The first part follows since the minimum is upper bounded by the expectation, taking $\beta=2^U$. The fact that $\phi(-x)=\phi(x)$  follows immediately from $Q_{\mathrm{FP} 4}(-x)=-Q_{\mathrm{FP} 4}(x)$. It remains to show that $\phi(x)\geq \phi_{\mathrm{min}}$ and that this minimum is attained for all $x\in \mathcal{I}_{\mathrm{FP4}}$. To that end, we first resort to the infinite exponent model of~\citet[Section III.B]{OP26surveyI}. In particular, define the ``$E\infty M 1$'' constellation
\begin{align}
	\mathcal \mathcal{C}_{E\infty M1}
	=\{0\}\cup
	\left\{\pm 2^k,\ \pm\tfrac32\,2^k:k\in\mathbb Z\right\},
\end{align}
which is clearly a superset of  $\mathcal{C}_{\mathrm{FP4}}$. Defining 
\begin{align}
	Q_{\infty}(x)=\operatorname*{\arg\!\min}_{\hat{x}\in\mathcal{C}_{E\infty M1}}|x-\hat{x}|,    
\end{align}
it therefore follows that
\begin{align}
g_\infty(v)&\triangleq \left(1-2^{-v}Q_\infty(2^v)\right)^2=2^{-2v}\left(2^v-Q_\infty(2^v)\right)^2\nonumber\\
&\leq 2^{-2v}\left(2^v-Q_{\mathrm{FP} 4}(2^v)\right)^2=g(v) ,~~\forall v\in\mathbb{R}.
\label{eq:EIbound}
\end{align}
Consequently
\begin{align}
\phi(2^t)=\int_{t-1}^{t}g(v)\,dv\geq \int_{t-1}^{t}g_\infty(v)\,dv
\stackrel{(a)}{=}\int_1^2 g_\infty(v)\,dv\stackrel{(b)}{=}\phi_{\mathrm{min}},
\label{eq:phiminbound}
\end{align}
where in $(a)$ we have used the fact that  $2^{-{(v+z)}}Q_\infty(2^{(v+z)})=2^{-{v}}Q_\infty(2^{v})$ for all $v\in\mathbb{R}$ and $z\in\mathbb{Z}$ (since $2^z\mathcal \mathcal{C}_{E\infty M1}=\mathcal \mathcal{C}_{E\infty M1}$). We now establish equality $(b)$ above . This follows since for any $x\in[2,4)$ we have that $Q_\infty(x)=\mathrm{round}(x)$, which implies also that for any $1\leq v<2$ it holds that $g_\infty(v)=(1-2^{-v}\mathrm{round}(2^v))^2$. Consequently
\begin{align}
\int_1^2 g_\infty(v)\,dv=\int_1^2 (1-2^{-v}\mathrm{round}(2^v))^2\,dv=\int_0^1 (1-2^{-{(u+1)}}\mathrm{round}(2^{(u+1)}))^2\,du=\phi_{\mathrm{min}}
\end{align}
as required.

The bound~\eqref{eq:phiminbound} holds with equality whenever ~\eqref{eq:EIbound} holds with equality.
Equality in~\eqref{eq:EIbound} in turn holds for all $v$ for which $Q_\infty(2^v)=Q_{\mathrm{FP} 4}(2^v)$. Noting that
\begin{align}
\mathcal \mathcal{C}_{E\infty M1}=\{\ldots, \tfrac34,\ 1,\ \tfrac32,\ 2,\ 3,\ 4,\ 6,\ 8,\ldots \}
\end{align}
we see that 
\begin{align}
Q_\infty(y)=Q_{\mathrm{FP} 4}(y)~~~ \forall y\in[7/8,7].
\end{align}
In particular, for any $x\in\mathcal{I}_{\mathrm{FP} }=[7/4,7]$ we have that $Q_\infty(x)=Q_{\mathrm{FP} 4}(x)$ on the entire interval $[x/2,x]$. Consequently, setting $t_x=\log_2(x)$ we see that for any $x\in\mathcal{I}_{\mathrm{FP} }=[7/4,7]$ it holds that $g(v)=g_\infty(v)$ for all $v\in [t_x-1,t_x]$ and therefore~\eqref{eq:EIbound} holds with equality for all $x\in\mathcal{I}_{\mathrm{FP} }=[7/4,7]$, as claimed.
